page_settings.custom_css:
/* cores e fontes do site (padrão Voucher Tec) */
:root{
  --blog-fundo:#FFFFFF;
  --blog-fundo-2:#F4F4F4;
  --blog-texto:#3C3D3D;
  --blog-texto-suave:#666666;
  --blog-titulo:#3C3D3D;
  --blog-acento:#E98300;
  --blog-acento-texto:#C56F00;
  --blog-fio:#E6E6E6;
  --blog-display:"Montserrat","Segoe UI",sans-serif;
  --blog-ui:"Roboto","Segoe UI",sans-serif;
  --blog-nav-h:0px;
  --blog-pad:max(16px,calc((100vw - 1140px) / 2));
  --blog-ease:cubic-bezier(.22,.61,.36,1);
  --blog-foto-filtro:none;
  --blog-capa-fundo:#3C3D3D;
  --blog-capa-filtro:brightness(.9);
  --blog-capa-scrim:linear-gradient(to top,rgba(0,0,0,.85) 0%,rgba(0,0,0,.45) 42%,rgba(0,0,0,.15) 74%,rgba(0,0,0,.45) 100%);
  --blog-capa-texto:#FFFFFF;
  --blog-capa-texto-suave:rgba(255,255,255,.75);
}
.blog-head .eyebrow{font-family:var(--blog-ui);font-size:12px;font-weight:600;letter-spacing:.28em;text-transform:uppercase;margin:0}
.blog-head-in{max-width:calc(760px + var(--blog-pad))}
.blog-head{background:var(--blog-fundo);color:var(--blog-texto);padding:0}
.blog-head-in{padding:calc(var(--blog-nav-h) + clamp(52px,7vw,96px)) var(--blog-pad) clamp(34px,4.5vw,56px);max-width:760px}
.blog-head h1{font-family:var(--blog-display);font-weight:400;font-size:clamp(34px,5vw,58px);line-height:1.08;color:var(--blog-titulo);margin:20px 0 16px}
.blog-head-in > p:not(.eyebrow){color:var(--blog-texto-suave);max-width:52ch;font-size:16.5px;line-height:1.6;margin:0}
.blog-head .eyebrow,.blog-cta .eyebrow{color:var(--blog-acento-texto)}
.blog-head-in{padding-left:var(--blog-pad)!important;padding-right:var(--blog-pad)!important;max-width:calc(760px + var(--blog-pad))}
@media (max-width:767px){.blog-head-in{padding-top:40px}}
.blog-head{background:transparent}
/* card do formulário */
.rt-cot-card{border-radius:10px;box-shadow:0 10px 40px rgba(0,0,0,.07)}
.rt-cot .jet-form-builder h2.wp-block-heading{font-family:Montserrat,sans-serif;font-size:24px;font-weight:600;color:#3C3D3D;margin:0 0 20px}
.rt-cot .jet-form-builder h4.wp-block-heading{font-family:Montserrat,sans-serif;font-size:17px!important;font-weight:600;color:#E98300;margin:36px 0 16px;padding-top:28px;border-top:1px solid #EEEEEE;text-transform:uppercase;letter-spacing:.06em}
.rt-cot .jet-form-builder-row{margin-bottom:18px}
.rt-cot .jet-form-builder__label-text{font-family:Roboto,sans-serif;font-size:15px;font-weight:500;color:#3C3D3D}
.rt-cot .jet-form-builder__required{color:#E98300}
.rt-cot .jet-form-builder__desc{font-size:13px;color:#8A8A8A;margin-top:6px}
.rt-cot .jet-form-builder__field.text-field,.rt-cot .jet-form-builder__field.select-field,.rt-cot .jet-form-builder__field.date-field,.rt-cot .jet-form-builder__field.textarea-field{width:100%;min-height:50px;padding:12px 14px;border:1px solid #D9D9D9;border-radius:8px;background:#FFFFFF;font-size:15px;color:#3C3D3D;box-shadow:none;transition:border-color .2s,box-shadow .2s}
.rt-cot .jet-form-builder__field.textarea-field{min-height:120px}
.rt-cot .jet-form-builder__field:focus{border-color:#E98300;box-shadow:0 0 0 3px rgba(233,131,0,.15);outline:0}
.rt-cot .checkradio-wrap .jet-form-builder__field-label{display:inline-flex;align-items:center;gap:10px;padding:6px 0;font-size:15px;color:#3C3D3D;cursor:pointer}
.rt-cot .radio-field{accent-color:#E98300;width:18px;height:18px}
.rt-cot .jet-form-builder__fields-group.checkradio-wrap{display:flex;flex-wrap:wrap;gap:4px 28px}
.rt-cot .jet-form-builder__submit{width:100%;margin-top:12px;padding:18px 32px;border:0;border-radius:8px;background:#E98300;color:#FFFFFF;font-family:Montserrat,sans-serif;font-size:16px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;cursor:pointer;transition:background .25s,transform .25s}
.rt-cot .jet-form-builder__submit:hover{background:#3C3D3D;transform:translateY(-2px)}
/* lateral */
@media (min-width:768px){.rt-cot-lado{position:sticky;top:110px}}
.rt-passos,.rt-contato{background:#FFFFFF;border-radius:10px;padding:30px 28px;box-shadow:0 10px 40px rgba(0,0,0,.05)}
.rt-passos h3,.rt-contato h3{font-family:Montserrat,sans-serif;font-size:20px;font-weight:600;color:#3C3D3D;margin:0 0 20px}
.rt-passos ol{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:20px}
.rt-passos li{display:flex;gap:16px;align-items:flex-start}
.rt-passos li span{flex:0 0 36px;height:36px;border-radius:50%;background:#E98300;color:#FFFFFF;font-family:Montserrat,sans-serif;font-weight:700;display:flex;align-items:center;justify-content:center}
.rt-passos strong{display:block;font-size:15px;color:#3C3D3D;margin-bottom:4px}
.rt-passos p{margin:0;font-size:14px;line-height:1.5;color:#777777}
.rt-contato p{margin:-10px 0 18px;font-size:14px;color:#777777}
.rt-contato a{display:block;text-align:center;border-radius:8px;padding:14px 18px;font-weight:600;text-decoration:none;transition:background .25s,color .25s}
.rt-contato .rt-zap{background:#25D366;color:#FFFFFF;margin-bottom:10px}
.rt-contato .rt-zap:hover{background:#1DA851;color:#FFFFFF}
.rt-contato .rt-mail{border:1px solid #D9D9D9;color:#3C3D3D;font-size:14px;word-break:break-all}
.rt-contato .rt-mail:hover{border-color:#E98300;color:#E98300}
